+        if a > b {
+            std::mem::swap(&mut a, &mut b);
+        }
+        if a.is_nan() || b.is_nan() {
+            return true;
+        }
+        t0 = t0.max(a);
+        t1 = t1.min(b);
+        if t0 > t1 {
+            return false;
+        }
+    }
+    true
+}

